17: export async function loadState(path: string): Promise<{ state: LocalState; warning?: string }> {
18:   let text: string;
19:   try {
20:     text = await readFile(path, 'utf8');
21:   } catch (cause) {
22:     if (isRecord(cause) && cause['code'] === 'ENOENT') return { state: emptyState };
23:     return { state: emptyState, warning: `Could not read local state: ${String(cause)}` };
24:   }
25:   try {
26:     return { state: parseState(JSON.parse(text)) };
27:   } catch (cause) {
28:     return {
29:       state: emptyState,
30:       warning: `Local state was unreadable and was reset: ${String(cause)}`,
31:     };
32:   }
33: }
34: 
35: export function parseState(raw: unknown): LocalState {
36:   if (!isRecord(raw) || raw['schemaVersion'] !== 1) return emptyState;
37:   const history: Record<string, string[]> = {};
38:   if (isRecord(raw['history'])) {
39:     for (const [key, entries] of Object.entries(raw['history'])) {
40:       if (Array.isArray(entries))
41:         history[key] = entries.filter((entry) => typeof entry === 'string');
42:     }
43:   }
44:   const recentModels: ModelSelection[] = [];
45:   if (Array.isArray(raw['recentModels'])) {
46:     for (const entry of raw['recentModels']) {
47:       if (!isRecord(entry)) continue;
48:       const { providerID, modelID, variant } = entry;
49:       if (typeof providerID !== 'string' || typeof modelID !== 'string') continue;
50:       recentModels.push({
51:         providerID,
52:         modelID,
53:         ...(typeof variant === 'string' ? { variant } : {}),
54:       });
55:     }
56:   }
57:   return { schemaVersion: 1, history, recentModels };
58: }
