60: /** Atomic save: write a temp file next to the target, then rename over it. */
61: export async function saveState(path: string, state: LocalState): Promise<void> {
62:   await mkdir(dirname(path), { recursive: true });
63:   const temp = `${path}.${process.pid}.tmp`;
64:   await writeFile(temp, `${JSON.stringify(state, null, 2)}\n`, { encoding: 'utf8', mode: 0o600 });
65:   await rename(temp, path);
66: }

