225:         kind: 'tool-group',
226:         key,
227:         summary: summarizeTools(tools),
228:         running: run.some((group) => group.running),
229:         tools,
230:         expanded: run.some((group) => group.expanded) || options.expandedGroups.has(key),
231:       });
232:     }
233:     run = [];
234:   };
235:   for (const node of nodes) {
236:     if (node.kind === 'tool-group') {
237:       run.push(node);
238:     } else {
239:       flush();
240:       merged.push(node);
241:     }
242:   }
243:   flush();
244:   return merged;
