247: function foldAssistant(
248:   message: Extract<TranscriptMessage, { kind: 'assistant' }>,
249:   options: FoldOptions,
250:   out: TranscriptNode[],
251: ): void {
252:   let pending: ToolCall[] = [];
253:   let sawReasoningText = false;
254:   const flush = () => {
255:     if (pending.length === 0) return;
256:     if (options.detailed) {
257:       for (const tool of pending) {
258:         out.push({
259:           kind: 'tool',
260:           key: tool.id,
261:           tool,
262:           category: classifyTool(tool.name),
263:           expanded: options.detailed,
264:         });
265:       }
266:     } else {
267:       const key = groupKey(pending);
268:       out.push({
269:         kind: 'tool-group',
270:         key,
271:         summary: summarizeTools(pending),
272:         running: pending.some((tool) => tool.status === 'running' || tool.status === 'streaming'),
273:         tools: pending,
274:         expanded: options.expandedGroups.has(key),
275:       });
276:     }
277:     pending = [];
278:   };
279:   message.parts.forEach((part, index) => {
280:     switch (part.kind) {
281:       case 'tool':
282:         if (isFoldable(part.tool)) {
283:           pending.push(part.tool);
284:           return;
285:         }
286:         flush();
287:         out.push({
288:           kind: 'tool',
289:           key: part.tool.id,
290:           tool: part.tool,
291:           category: classifyTool(part.tool.name),
292:           expanded:
293:             options.detailed ||
294:             part.tool.status === 'error' ||
295:             options.expandedDiffs?.has(part.tool.id) === true,
296:         });
297:         return;
298:       case 'text':
299:         if (part.text.trim() === '') return;
300:         flush();
301:         out.push({ kind: 'text', key: `${message.id}:${index}`, text: part.text });
302:         return;
303:       case 'reasoning':
304:         if (part.text.trim() !== '') sawReasoningText = true;
305:         // Live reasoning status is the throbber's job; the transcript only shows
306:         // authentic reasoning text, and only in detailed mode.
307:         if (options.detailed && part.text.trim() !== '') {
308:           flush();
309:           out.push({
310:             kind: 'reasoning',
311:             key: `${message.id}:${index}`,
312:             text: part.text,
313:             done: part.done,
314:           });
315:         }
316:         return;
317:       default:
318:         assertNever(part);
319:     }
320:   });
321:   flush();
322:   if (
323:     options.detailed &&
324:     !sawReasoningText &&
325:     message.reasoningTokens !== undefined &&
326:     message.reasoningTokens > 0
327:   ) {
328:     out.push({
329:       kind: 'reasoning-unavailable',
330:       key: `${message.id}:reasoning`,
331:       tokens: message.reasoningTokens,
332:     });
333:   }
334:   if (message.error !== undefined) {
335:     out.push({ kind: 'notice', key: `${message.id}:error`, text: message.error, tone: 'error' });
336:   }
337: }
