82: export function describeThrobber(
83:   facts: ThrobberFacts,
84:   now: number,
85:   width: number,
86:   formatTime: (at: number) => string,
87: ): ThrobberLine {
88:   const tokens =
89:     facts.outputTokens === undefined ? undefined : `${compactTokens(facts.outputTokens)} tokens`;
90:   if (facts.phase === 'running') {
91:     const elapsed = now - facts.startedAt;
92:     const label = `${facts.activity ?? verbAt(facts.startedAt, elapsed)}…`;
93:     const parts = [formatElapsed(elapsed), ...(tokens === undefined ? [] : [`↓ ${tokens}`])];
94:     return {
95:       label,
96:       meta: fit(label, `(${parts.join(' · ')})`, width, `(${parts[0]})`),
97:       animated: true,
98:     };
99:   }
100:   const status =
101:     facts.phase === 'completed'
102:       ? `Finished at ${formatTime(facts.completedAt ?? now)}`
103:       : facts.phase === 'interrupted'
104:         ? 'Interrupted'
105:         : 'Failed';
106:   const full = tokens === undefined ? status : `${status} · ${tokens}`;
107:   return { label: '', meta: fit('', full, width, status), animated: false };
