142:  * Indicator facts for the latest turn, derived only from canonical messages and the
143:  * server's running flag. Returns undefined when there is no turn to describe.
144:  */
145: export function latestTurn(
146:   messages: readonly TranscriptMessage[],
147:   running: boolean,
148: ): ThrobberFacts | undefined {
149:   const userIndex = messages.findLastIndex((message) => message.kind === 'user');
150:   const user = messages[userIndex];
151:   if (user === undefined) return undefined;
152:   const after = messages.slice(userIndex + 1);
153:   const assistant = after.findLast((message) => message.kind === 'assistant');
154:   if (running) {
155:     const lastPart = assistant?.kind === 'assistant' ? assistant.parts.at(-1) : undefined;
156:     const compacting = after.some(
157:       (message) => message.kind === 'compaction' && message.state === 'running',
158:     );
159:     const activity = compacting
160:       ? 'Compacting conversation'
161:       : lastPart?.kind === 'tool' && lastPart.tool.status !== 'completed'
162:         ? activityByCategory[classifyTool(lastPart.tool.name)]
163:         : lastPart?.kind === 'reasoning' && !lastPart.done
164:           ? 'Thinking'
165:           : undefined;
166:     return {
167:       phase: 'running',
168:       startedAt: user.createdAt,
169:       ...(activity === undefined ? {} : { activity }),
170:     };
171:   }
172:   const idle = after.findLast((message) => message.kind === 'idle');
173:   if (idle === undefined && assistant === undefined) return undefined;
174:   const failed =
175:     (idle?.kind === 'idle' && idle.outcome === 'failed') ||
176:     (assistant?.kind === 'assistant' && assistant.error !== undefined);
177:   const phase: ThrobberPhase =
178:     idle?.kind === 'idle' && idle.outcome === 'interrupted'
179:       ? 'interrupted'
180:       : failed
181:         ? 'failed'
182:         : 'completed';
183:   const completedAt =
184:     idle?.createdAt ?? (assistant?.kind === 'assistant' ? assistant.completedAt : undefined);
185:   return {
186:     phase,
187:     startedAt: user.createdAt,
188:     ...(completedAt === undefined ? {} : { completedAt }),
189:   };
190: }

