47: /**
48:  * A unified diff for an edit-like tool call. Prefers the server's own diff (real
49:  * file line numbers); otherwise synthesises one from the old and new text, where
50:  * numbering starts at 1 because the file's position is unknown.
51:  */
52: export function editDiff(tool: ToolCall): EditDiff | undefined {
53:   const path = text(tool.input['filePath']) ?? text(tool.input['path']);
54:   if (path === undefined) return undefined;
55:   const filetype = filetypeOf(path);
56:   if (tool.diff !== undefined && tool.diff.trim() !== '') return { diff: tool.diff, filetype };
57:   const oldText = text(tool.input['oldString']);
58:   const newText = text(tool.input['newString']);
59:   if (oldText !== undefined && newText !== undefined) {
60:     return { diff: unified(path, lines(oldText), lines(newText)), filetype };
61:   }
62:   const content = text(tool.input['content']);
63:   if (tool.name === 'write' && content !== undefined) {
64:     return { diff: unified(path, [], lines(content)), filetype };
65:   }
66:   return undefined;
67: }
