69: function unified(path: string, removed: readonly string[], added: readonly string[]): string {
70:   const head = `--- a/${path}\n+++ b/${path}\n@@ -${removed.length === 0 ? 0 : 1},${removed.length} +${added.length === 0 ? 0 : 1},${added.length} @@`;
71:   return [head, ...removed.map((line) => `-${line}`), ...added.map((line) => `+${line}`)].join(
72:     '\n',
73:   );
74: }
