76: /** `+18 −7` counts for a unified diff. */
77: export function diffCounts(diff: string): { additions: number; deletions: number } {
78:   let additions = 0;
79:   let deletions = 0;
80:   for (const line of diff.split('\n')) {
81:     if (line.startsWith('+++') || line.startsWith('---')) continue;
82:     if (line.startsWith('+')) additions += 1;
83:     else if (line.startsWith('-')) deletions += 1;
84:   }
85:   return { additions, deletions };
86: }
