91: export type DiffPreview = Readonly<{
92:   /** The first `budget` display lines, unparsed for safe clipping. */
93:   shown: readonly PatchLine[];
94:   /** How many display lines are hidden behind the expand control. */
95:   hidden: number;
96: }>;
