98: /**
99:  * Explicit display-line clipping of a patch for compact rendering. Never feeds a
100:  * truncated patch back into a unified-diff parser; callers render `shown` verbatim.
101:  */
102: export function clampDiffPatch(patch: string, budget: number = diffPreviewBudget): DiffPreview {
103:   const clipped = patchLines(patch);
104:   if (clipped.length <= budget) return { shown: clipped, hidden: 0 };
105:   return { shown: clipped.slice(0, budget), hidden: clipped.length - budget };
106: }
