108: /** True when an edit-like tool's patch exceeds the compact-mode preview budget. */
109: export function hasOversizedDiff(tool: ToolCall, budget: number = diffPreviewBudget): boolean {
110:   const edit = editDiff(tool);
111:   if (edit === undefined) return false;
112:   return patchLines(edit.diff).length > budget;
113: }

