40: /**
41:  * Classifies submitted composer text. `/name` is only a command at the very start;
42:  * `!` at the start is user shell mode. A local verb is never sent as a model prompt.
43:  */
44: export function parseInput(text: string, serverCommands: ReadonlySet<string>): ParsedInput {
45:   if (text.startsWith('!')) return { kind: 'shell', command: text.slice(1).trim() };
46:   if (!text.startsWith('/')) return { kind: 'prompt', text };
47:   const match = /^\/(\S+)\s*([\s\S]*)$/.exec(text);
48:   if (match === null) return { kind: 'prompt', text };
49:   const name = match[1] ?? '';
50:   const args = (match[2] ?? '').trim();
51:   if (isLocalCommand(name)) {
52:     if (name === 'server') {
53:       const inner = /^(\S+)\s*([\s\S]*)$/.exec(args);
54:       if (inner === null) return { kind: 'unknown-command', name: 'server' };
55:       return { kind: 'server', name: inner[1] ?? '', args: (inner[2] ?? '').trim() };
56:     }
57:     return { kind: 'local', name, args };
58:   }
59:   if (serverCommands.has(name)) return { kind: 'server', name, args };
60:   return { kind: 'unknown-command', name };
61: }
