68: export function completeCommand(
69:   text: string,
70:   serverCommands: readonly { name: string; description?: string }[],
71: ): { name: string; description: string }[] {
72:   if (!text.startsWith('/') || /\s/.test(text)) return [];
73:   const prefix = text.slice(1);
74:   const local = Object.entries(localCommands)
75:     .filter(([name]) => name.startsWith(prefix))
76:     .map(([name, description]) => ({ name, description }));
77:   const server = serverCommands
78:     .filter((command) => command.name.startsWith(prefix) && !isLocalCommand(command.name))
79:     .map((command) => ({
80:       name: command.name,
81:       description: command.description ?? 'server command',
82:     }));
83:   return [...local, ...server];
