262:     switch (key.name) {
263:       case 'c':
264:         if (controller.isRunning()) void controller.interrupt();
265:         else if (composer.text !== '') edit(emptyComposer);
266:         else controller.armOrExit('Ctrl+C');
267:         return true;
268:       case 'd':
269:         if (composer.text !== '') return edit(deleteForward(composer));
270:         controller.armOrExit('Ctrl+D');
271:         return true;
272:       case 'a':
273:         return edit(moveLineStart(composer));
274:       case 'e':
275:         return edit(moveLineEnd(composer));
276:       case 'w':
277:       case 'backspace':
278:         return edit(deleteWordBackward(composer));
279:       case 'u':
280:         return edit(deleteToLineStart(composer));
281:       case 'k':
282:         return edit(deleteToLineEnd(composer));
283:       case 'p':
284:         controller.historyUp();
285:         return true;
286:       case 'n':
287:         controller.historyDown();
288:         return true;
289:       case 'left':
290:         return edit(moveWordLeft(composer));
291:       case 'right':
292:         return edit(moveWordRight(composer));
293:       default:
294:         return false;
295:     }
296:   }
297:   if (key.alt) {
298:     if (key.name === 'b' || key.name === 'left') return edit(moveWordLeft(composer));
299:     if (key.name === 'f' || key.name === 'right') return edit(moveWordRight(composer));
300:     if (key.name === 'backspace') return edit(deleteWordBackward(composer));
301:     if (key.name === 'return') {
302:       void controller.steer();
303:       return true;
304:     }
305:   }
306: 
307:   switch (key.name) {
308:     case 'return':
309:     case 'enter':
310:       if (key.shift) return edit(insertText(composer, '\n'));
311:       // An empty prompt gives Enter the selected tool group first; otherwise it submits.
312:       if (composer.text === '' && controller.toggleFocusedGroup()) return true;
313:       void controller.submit();
314:       return true;
315:     case 'linefeed':
316:       return edit(insertText(composer, '\n'));
317:     case 'backspace':
318:       return edit(deleteBackward(composer));
319:     case 'delete':
320:       return edit(deleteForward(composer));
321:     case 'left':
322:       if (state.route.kind !== 'overview' && leftOpensOverview(composer, blockers(controller))) {
323:         controller.openOverview();
324:         return true;
325:       }
326:       return edit(moveLeft(composer));
327:     case 'right':
328:       return edit(moveRight(composer));
329:     case 'home':
330:       return edit(moveLineStart(composer));
331:     case 'end':
332:       return edit(moveLineEnd(composer));
333:     case 'up': {
334:       const moved = moveVertical(composer, -1);
335:       if (moved !== undefined) return edit(moved);
336:       if (state.route.kind === 'overview' && composer.text === '') {
337:         controller.moveOverviewSelection(-1);
338:         return true;
339:       }
340:       controller.historyUp();
341:       return true;
342:     }
343:     case 'down': {
344:       const moved = moveVertical(composer, 1);
345:       if (moved !== undefined) return edit(moved);
346:       controller.historyDown();
347:       return true;
348:     }
349:     case 'escape':
350:       controller.clearGroupFocus();
351:       if (state.exitArmed || state.notice !== undefined) controller.clearNotice();
352:       return true;
353:     case 'tab':
354:       return true;
355:     default:
356:       break;
357:   }
358:   if (isPrintable(key)) return edit(insertText(composer, key.text));
359:   return false;
360: }
